export default function RandomThinkingSvg() {
    const randNum = Math.floor(Math.random() * 7) + 1

    switch (randNum) {
        case 1: return <ThinkingSvg1 />
        case 2: return <ThinkingSvg2 />
        case 3: return <ThinkingSvg3 />
        case 4: return <ThinkingSvg4 />
        case 5: return <ThinkingSvg5 />
        case 6: return <ThinkingSvg6 />
        case 7: return <ThinkingSvg7 />
        default: return <ThinkingSvg1 />
    }
}